# fix_chat.py
import zlib, base64, os, sys, re, glob, subprocess

URLS_B64 = ""
CHAT_B64 = ""
FEED_B64 = ""
VIEWS_BLOCK_B64 = ""

def apply_fix():
    base = os.path.dirname(os.path.abspath(__file__))
    
    # 1. Update portal/urls.py
    urls_path = os.path.join(base, 'portal', 'urls.py')
    with open(urls_path, 'wb') as f:
        f.write(zlib.decompress(base64.b64decode(URLS_B64)))
    print('Updated portal/urls.py (chat send & message routes added)')

    # 2. Update templates/chat.html
    chat_path = os.path.join(base, 'templates', 'chat.html')
    with open(chat_path, 'wb') as f:
        f.write(zlib.decompress(base64.b64decode(CHAT_B64)))
    print('Updated templates/chat.html (tagged post banner & send handling added)')

    # 3. Update templates/dashboard_social_feed.html
    feed_path = os.path.join(base, 'templates', 'dashboard_social_feed.html')
    with open(feed_path, 'wb') as f:
        f.write(zlib.decompress(base64.b64decode(FEED_B64)))
    print('Updated templates/dashboard_social_feed.html (query params & chat recipient added)')

    # 4. Patch portal/views.py
    views_path = os.path.join(base, 'portal', 'views.py')
    with open(views_path, 'r', encoding='utf-8') as f:
        v_text = f.read()

    new_block = zlib.decompress(base64.b64decode(VIEWS_BLOCK_B64)).decode('utf-8')
    pattern = r'(def _build_all_modules_social_feed\(user\):[\s\S]*?\n)(?=def user_has_manage_logins_permission)'
    if re.search(pattern, v_text):
        v_text = re.sub(pattern, lambda m: new_block, v_text)
        with open(views_path, 'w', encoding='utf-8') as f:
            f.write(v_text)
        print('Updated portal/views.py (_build_all_modules_social_feed & post_router_view)')
    else:
        print('Notice: pattern in views.py not matched directly, checking if already updated.')

    # 5. Touch WSGI to reload PythonAnywhere web app
    wsgi_files = glob.glob('/var/www/*_wsgi.py')
    for wf in wsgi_files:
        try:
            os.utime(wf, None)
            print(f'Reloaded Web App: {wf}')
        except Exception as e:
            print(f'WSGI note: {e}')

    # 6. Collectstatic
    python_exe = sys.executable or 'python'
    manage_py = os.path.join(base, 'manage.py')
    if os.path.exists(manage_py):
        subprocess.run([python_exe, manage_py, 'collectstatic', '--noinput'], check=False)

    print('\n========================================')
    print('SUCCESS: Chat sending and tagging fix applied!')
    print('========================================')

if __name__ == '__main__':
    apply_fix()
